final class RetryPolicy {
    private final Optional<Integer> maxRetries;

    RetryPolicy(Map<String, String> props) {
        maxRetries = Setting.RETRIES.find(props);
    }

    int attemptsLeft(int used) {
        return maxRetries.orElse(3) - used;
    }
